from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    if n == 0:
        return 1
    m = len(alphabet)
    if not banned:
        return pow(m, n, MOD)

    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}
    transitions = [[-1] * m]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = transitions[node][c]
            if nxt == -1:
                nxt = len(transitions)
                transitions[node][c] = nxt
                transitions.append([-1] * m)
                bad.append(False)
            node = nxt
        bad[node] = True

    num_nodes = len(transitions)
    fail = [0] * num_nodes
    queue = deque()

    for c in range(m):
        nxt = transitions[0][c]
        if nxt != -1:
            fail[nxt] = 0
            queue.append(nxt)
        else:
            transitions[0][c] = 0

    while queue:
        u = queue.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(m):
            nxt = transitions[u][c]
            if nxt != -1:
                fail[nxt] = transitions[fail[u]][c]
                if bad[u]:
                    bad[nxt] = True
                queue.append(nxt)
            else:
                transitions[u][c] = transitions[fail[u]][c]

    good = [u for u in range(num_nodes) if not bad[u]]
    k = len(good)
    state_id = {u: i for i, u in enumerate(good)}

    base = [[0] * k for _ in range(k)]
    for i, u in enumerate(good):
        row = base[i]
        for c in range(m):
            v = transitions[u][c]
            if not bad[v]:
                row[state_id[v]] += 1

    vec = [0] * k
    vec[0] = 1
    exp = n
    while exp > 0:
        if exp & 1:
            new_vec = [0] * k
            for i in range(k):
                vi = vec[i]
                if vi:
                    row = base[i]
                    for j in range(k):
                        new_vec[j] += vi * row[j]
            vec = [x % MOD for x in new_vec]
        exp >>= 1
        if exp:
            new_base = [[0] * k for _ in range(k)]
            for i in range(k):
                row_i = base[i]
                res_i = new_base[i]
                for t in range(k):
                    a = row_i[t]
                    if a:
                        row_t = base[t]
                        for j in range(k):
                            res_i[j] += a * row_t[j]
                for j in range(k):
                    res_i[j] %= MOD
            base = new_base

    return sum(vec) % MOD
